# -*- coding: utf-8 -*-
"""France / Sciences et technologie : 6e（cycle 3）"""
from fr_sci import H, nq, num


def f_mv(R):
    k = R.choice(["rho", "rho", "m", "V", "comp"])
    if k == "rho":
        m, V = R.choice([(270, 100), (79, 10), (50, 50), (180, 200), (540, 200), (89, 10), (23, 25), (113, 10)])
        return nq("Un objet a une masse de %s g et un volume de %s cm³. Combien de grammes pèse 1 cm³ de cette matière ?" % (num(m), num(V)), m / V,
                  [V / m, m * V, m - V], "g/cm³", "%s : %s = %s g par cm³." % (num(m), num(V), num(m / V)))
    if k == "m":
        r, V, n = R.choice([(1, 250, "d’eau"), (2.7, 20, "d’aluminium"), (7.9, 10, "de fer"), (0.8, 100, "d’huile"), (1, 75, "d’eau"), (0.9, 50, "de glace"), (2.7, 100, "d’aluminium"), (19.3, 10, "d’or")])
        return nq("1 cm³ %s pèse %s g. Quelle est la masse de %s cm³ %s ?" % (n, num(r), num(V), n), r * V, [V / r, r + V, V], "g", "%s × %s = %s g." % (num(V), num(r), num(r * V)))
    if k == "V":
        r, m, n = R.choice([(1, 300, "d’eau"), (2.7, 54, "d’aluminium"), (7.9, 158, "de fer"), (0.8, 40, "d’huile"), (1, 125, "d’eau")])
        return nq("1 cm³ %s pèse %s g. Quel volume occupent %s g %s ?" % (n, num(r), num(m), n), m / r, [m * r, m + r, r], "cm³", "%s : %s = %s cm³." % (num(m), num(r), num(m / r)))
    a, b = R.choice([((100, 100), (100, 92)), ((50, 135), (50, 50)), ((20, 158), (20, 54)), ((10, 9), (10, 10))])
    ra, rb = a[1] / a[0], b[1] / b[0]
    return nq("Deux cubes ont le même volume (%s cm³). L’un pèse %s g, l’autre %s g. Quel est l’écart de masse ?" % (num(a[0]), num(a[1]), num(b[1])), abs(a[1] - b[1]),
              [a[1] + b[1], abs(ra - rb), max(a[1], b[1])], "g", "%s − %s = %s g : à volume égal, la masse dépend de la matière." % (num(max(a[1], b[1])), num(min(a[1], b[1])), num(abs(a[1] - b[1]))))


def f_vit(R):
    k = R.choice(["v", "v", "d", "t", "comp"])
    if k == "v":
        d, t, who = R.choice([(12, 3, "Un cycliste"), (150, 2, "Une voiture"), (10, 2, "Un coureur"), (300, 3, "Un TGV"), (60, 4, "Un cycliste"), (8, 2, "Un marcheur"), (45, 3, "Un bus")])
        return nq("%s parcourt %s km en %s h. Quelle est sa vitesse moyenne ?" % (who, num(d), num(t)), d / t, [d * t, t / d, d - t], "km/h", "v = d : t = %s : %s = %s km/h." % (num(d), num(t), num(d / t)))
    if k == "d":
        v, t = R.choice([(5, 2), (20, 3), (90, 2), (300, 2), (15, 4), (60, 3)])
        return nq("Un objet se déplace à %s km/h pendant %s h. Quelle distance parcourt-il ?" % (num(v), num(t)), v * t, [v / t, v + t, t / v * 100], "km", "d = v × t = %s × %s = %s km." % (num(v), num(t), num(v * t)))
    if k == "t":
        d, v = R.choice([(20, 5), (60, 20), (180, 90), (600, 300), (12, 4), (45, 15)])
        return nq("Il faut parcourir %s km à %s km/h. Combien d’heures faut-il ?" % (num(d), num(v)), d / v, [d * v, v / d, d - v], "h", "t = d : v = %s : %s = %s h." % (num(d), num(v), num(d / v)))
    d1, t1, d2, t2 = R.choice([(100, 20, 100, 25), (60, 10, 60, 12), (200, 40, 150, 25), (80, 16, 120, 20)])
    v1, v2 = d1 / t1, d2 / t2
    return nq("Léa court %s m en %s s, Hugo %s m en %s s. Quelle est la vitesse du plus rapide ?" % (num(d1), num(t1), num(d2), num(t2)), max(v1, v2),
              [min(v1, v2), d1 + d2, (t1 + t2) / 2], "m/s", "Léa : %s m/s, Hugo : %s m/s." % (num(v1), num(v2)))


